import { useState } from 'react';
import { createProject } from '../db/firestore';
import { handleGenerateQueries } from '../api/generateQueries';
import { handleRunSimulation } from '../api/runSimulation';
import { Loader2, Plus } from 'lucide-react';

interface ProjectFormProps {
  onProjectCreated: () => void;
}

export const ProjectForm = ({ onProjectCreated }: ProjectFormProps) => {
  const [name, setName] = useState('');
  const [keyword, setKeyword] = useState('');
  const [competitors, setCompetitors] = useState('');
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setStatus('Creating project...');

    try {
      const projectId = await createProject({
        name,
        targetKeyword: keyword,
        status: 'active'
      });

      setStatus('Generating queries...');
      const queryResult = await handleGenerateQueries({
        keyword,
        projectId
      });

      if (!queryResult.success) {
        throw new Error(queryResult.error || 'Failed to generate queries');
      }

      setStatus('Running simulation...');
      const competitorsList = competitors
        .split(',')
        .map(c => c.trim())
        .filter(c => c.length > 0);

      const simResult = await handleRunSimulation({
        queryIds: queryResult.queryIds,
        competitors: competitorsList
      });

      if (!simResult.success) {
        throw new Error(simResult.error || 'Failed to run simulation');
      }

      setStatus('Project created successfully!');
      setName('');
      setKeyword('');
      setCompetitors('');
      onProjectCreated();
    } catch (error) {
      setStatus(`Error: ${error}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-lg shadow p-6">
      <div className="flex items-center gap-2 mb-6">
        <Plus className="w-6 h-6 text-blue-600" />
        <h2 className="text-xl font-semibold text-slate-900">Create New Project</h2>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2">
            Project Name
          </label>
          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="My GEO Project"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2">
            Target Keyword
          </label>
          <input
            type="text"
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            required
            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="강남 피부과"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2">
            Competitors (comma-separated)
          </label>
          <input
            type="text"
            value={competitors}
            onChange={(e) => setCompetitors(e.target.value)}
            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="경쟁사A, 경쟁사B, 경쟁사C"
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-4 rounded-lg transition-colors disabled:bg-slate-400 disabled:cursor-not-allowed flex items-center justify-center gap-2"
        >
          {loading ? (
            <>
              <Loader2 className="w-5 h-5 animate-spin" />
              Processing...
            </>
          ) : (
            'Create Project & Run Analysis'
          )}
        </button>

        {status && (
          <div className={`p-4 rounded-lg ${loading ? 'bg-blue-50 text-blue-700' : 'bg-green-50 text-green-700'}`}>
            {status}
          </div>
        )}
      </form>
    </div>
  );
};
