import OpenAI from 'openai';

let openaiClient: OpenAI | null = null;

const getOpenAIClient = (): OpenAI => {
  if (!openaiClient) {
    const apiKey = import.meta.env.VITE_OPENAI_API_KEY;

    if (!apiKey) {
      throw new Error('OpenAI API key is not configured. Please add VITE_OPENAI_API_KEY to your environment variables.');
    }

    openaiClient = new OpenAI({
      apiKey,
      dangerouslyAllowBrowser: true
    });
  }

  return openaiClient;
};

export const askLLM = async (prompt: string, systemPrompt?: string): Promise<string> => {
  try {
    const openai = getOpenAIClient();

    const messages: OpenAI.Chat.ChatCompletionMessageParam[] = [];

    if (systemPrompt) {
      messages.push({
        role: 'system',
        content: systemPrompt
      });
    }

    messages.push({
      role: 'user',
      content: prompt
    });

    const response = await openai.chat.completions.create({
      model: 'gpt-4o-mini',
      messages,
      temperature: 0.7,
      max_tokens: 2000
    });

    return response.choices[0]?.message?.content || '';
  } catch (error) {
    console.error('OpenAI API Error:', error);
    throw new Error(`Failed to get response from OpenAI: ${error}`);
  }
};

export const generateQueries = async (keyword: string): Promise<string[]> => {
  const prompt = `다음 키워드와 관련된 검색 질문 30개를 생성해주세요: "${keyword}"

요구사항:
- 실제 사용자가 검색할 법한 자연스러운 질문
- 다양한 검색 의도 포함 (정보 탐색, 비교, 추천 등)
- 지역 기반 질문 포함
- 각 질문은 한 줄로 작성
- 번호나 불릿 없이 질문만 작성

예시 형식:
${keyword} 추천
${keyword} 가격 비교
근처 ${keyword} 어디가 좋을까요`;

  const response = await askLLM(prompt);

  const queries = response
    .split('\n')
    .map(line => line.trim())
    .filter(line => line.length > 0)
    .slice(0, 30);

  return queries;
};

export const simulateAIAnswer = async (query: string): Promise<string> => {
  const systemPrompt = `당신은 사용자의 질문에 정확하고 유용한 답변을 제공하는 AI 어시스턴트입니다.`;

  const response = await askLLM(query, systemPrompt);
  return response;
};

export const generateContent = async (
  query: string,
  targetBrand: string,
  contentType: 'qa' | 'list' | 'comparison'
): Promise<string> => {
  let prompt = '';

  switch (contentType) {
    case 'qa':
      prompt = `다음 질문에 대한 상세한 Q&A 콘텐츠를 작성해주세요.
질문: ${query}
브랜드: ${targetBrand}

요구사항:
- 질문에 대한 명확한 답변
- ${targetBrand}를 자연스럽게 언급
- 실용적이고 유용한 정보 제공
- 블로그 포스트 형식`;
      break;

    case 'list':
      prompt = `다음 주제에 대한 추천 리스트 콘텐츠를 작성해주세요.
주제: ${query}
포함 브랜드: ${targetBrand}

요구사항:
- 5-7개의 추천 항목 리스트
- ${targetBrand}를 상위권에 포함
- 각 항목에 대한 간단한 설명
- 객관적이고 신뢰할 수 있는 톤`;
      break;

    case 'comparison':
      prompt = `다음 주제에 대한 비교 콘텐츠를 작성해주세요.
주제: ${query}
비교 대상: ${targetBrand} 포함

요구사항:
- 3-5개 옵션 비교
- ${targetBrand}의 장점 강조
- 객관적인 비교 기준 제시
- 표 형식 또는 구조화된 비교`;
      break;
  }

  const response = await askLLM(prompt);
  return response;
};

export const generateContentVariations = async (
  originalContent: string,
  count: number = 3
): Promise<string[]> => {
  const prompt = `다음 콘텐츠의 변형 버전 ${count}개를 생성해주세요.

원본 콘텐츠:
${originalContent}

요구사항:
- 핵심 메시지는 유지
- 표현과 구조를 다르게
- 각 변형은 "---VARIATION---"으로 구분
- 자연스럽고 독창적인 내용`;

  const response = await askLLM(prompt);

  const variations = response
    .split('---VARIATION---')
    .map(v => v.trim())
    .filter(v => v.length > 0)
    .slice(0, count);

  return variations;
};
