import {
  collection,
  doc,
  addDoc,
  getDoc,
  getDocs,
  updateDoc,
  deleteDoc,
  query,
  where,
  orderBy,
  Timestamp,
  writeBatch
} from 'firebase/firestore';
import { db, auth } from '../config/firebase';

const getUserId = (): string => {
  const user = auth.currentUser;
  if (!user) {
    throw new Error('User must be authenticated to perform this action');
  }
  return user.uid;
};

export const COLLECTIONS = {
  PROJECTS: 'jkai011_projects',
  QUERIES: 'jkai011_queries',
  ANSWERS: 'jkai011_answers',
  METRICS: 'jkai011_metrics',
  CONTENTS: 'jkai011_contents',
  JOBS: 'jkai011_jobs',
  MEMBERS: 'jkai011_members',
  USER_SHARED: 'jkai011_user_shared'
} as const;

export interface Project {
  id?: string;
  userId: string;
  name: string;
  targetKeyword: string;
  status: 'active' | 'completed' | 'archived';
  createdAt: Timestamp;
  updatedAt: Timestamp;
}

export interface QueryDoc {
  id?: string;
  projectId: string;
  text: string;
  cluster?: string;
  intent?: string;
  createdAt: Timestamp;
}

export interface Answer {
  id?: string;
  queryId: string;
  platform: string;
  answer: string;
  entities: string[];
  positions: Record<string, number>;
  rawResponse: string;
  createdAt: Timestamp;
}

export interface Metric {
  id?: string;
  queryId: string;
  projectId: string;
  mention: boolean;
  position: number | null;
  isRecommended: boolean;
  competitors: string[];
  score: number;
  createdAt: Timestamp;
}

export interface Content {
  id?: string;
  projectId: string;
  queryId: string;
  type: 'qa' | 'list' | 'comparison' | 'variation';
  content: string;
  variationIndex?: number;
  status: 'draft' | 'published' | 'archived';
  createdAt: Timestamp;
}

export interface Job {
  id?: string;
  type: 'simulation' | 'content_generation';
  status: 'pending' | 'running' | 'completed' | 'failed';
  payload: Record<string, any>;
  resultSummary?: Record<string, any>;
  createdAt: Timestamp;
  updatedAt: Timestamp;
}

export interface JobLog {
  message: string;
  level: 'info' | 'error';
  createdAt: Timestamp;
  expireAt: Timestamp;
}

export interface ProjectMember {
  id?: string;
  projectId: string;
  userId: string;
  userEmail: string;
  role: 'owner' | 'editor' | 'viewer';
  addedBy: string;
  createdAt: Timestamp;
}

export const createProject = async (project: Omit<Project, 'id' | 'userId' | 'createdAt' | 'updatedAt'>) => {
  const userId = getUserId();
  const now = Timestamp.now();
  const docRef = await addDoc(collection(db, COLLECTIONS.PROJECTS), {
    ...project,
    userId,
    createdAt: now,
    updatedAt: now
  });
  return docRef.id;
};

