export const updateJob = async (jobId: string, updates: Partial<Job>) => {
  const jobRef = doc(db, COLLECTIONS.JOBS, jobId);
  await updateDoc(jobRef, {
    ...updates,
    updatedAt: Timestamp.now()
  });
};

export const addJobLog = async (jobId: string, log: Omit<JobLog, 'createdAt' | 'expireAt'>) => {
  const now = Timestamp.now();
  const expireAt = new Timestamp(now.seconds + 7 * 24 * 60 * 60, 0);

  await addDoc(collection(db, COLLECTIONS.JOBS, jobId, 'logs'), {
    ...log,
    createdAt: now,
    expireAt
  });
};

export const getProject = async (projectId: string): Promise<Project | null> => {
  const docRef = doc(db, COLLECTIONS.PROJECTS, projectId);
  const docSnap = await getDoc(docRef);

  if (docSnap.exists()) {
    return { id: docSnap.id, ...docSnap.data() } as Project;
  }
  return null;
};

export const getQueryDoc = async (queryId: string): Promise<QueryDoc | null> => {
  const docRef = doc(db, COLLECTIONS.QUERIES, queryId);
  const docSnap = await getDoc(docRef);

  if (docSnap.exists()) {
    return { id: docSnap.id, ...docSnap.data() } as QueryDoc;
  }
  return null;
};

export const getQueriesByProject = async (projectId: string): Promise<QueryDoc[]> => {
  const q = query(
    collection(db, COLLECTIONS.QUERIES),
    where('projectId', '==', projectId),
    orderBy('createdAt', 'desc')
  );

  const querySnapshot = await getDocs(q);
  return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as QueryDoc));
};

export const getMetricsByProject = async (projectId: string): Promise<Metric[]> => {
  const q = query(
    collection(db, COLLECTIONS.METRICS),
    where('projectId', '==', projectId),
    orderBy('createdAt', 'desc')
  );

  const querySnapshot = await getDocs(q);
  return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Metric));
};

export const getAllProjects = async (): Promise<Project[]> => {
  const userId = getUserId();
  const user = auth.currentUser;

  const ownedQuery = query(
    collection(db, COLLECTIONS.PROJECTS),
    where('userId', '==', userId),
    orderBy('createdAt', 'desc')
  );
  const ownedSnapshot = await getDocs(ownedQuery);
  const ownedProjects = ownedSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Project));

  const sharedProjects: Project[] = [];
  if (user?.email) {
    const sharedProjectsRef = collection(db, COLLECTIONS.USER_SHARED, user.email, COLLECTIONS.PROJECTS);
    const sharedSnapshot = await getDocs(sharedProjectsRef);

    for (const sharedDoc of sharedSnapshot.docs) {
      const projectId = sharedDoc.data().projectId;
      const projectDoc = await getDoc(doc(db, COLLECTIONS.PROJECTS, projectId));
      if (projectDoc.exists()) {
        sharedProjects.push({ id: projectDoc.id, ...projectDoc.data() } as Project);
      }
    }
  }

  const allProjects = [...ownedProjects, ...sharedProjects];
  const uniqueProjects = Array.from(
    new Map(allProjects.map(p => [p.id, p])).values()
  );

  return uniqueProjects.sort((a, b) => b.createdAt.seconds - a.createdAt.seconds);
};

export const deleteProject = async (projectId: string): Promise<void> => {
  const userId = getUserId();
  const projectRef = doc(db, COLLECTIONS.PROJECTS, projectId);
  const projectSnap = await getDoc(projectRef);

  if (!projectSnap.exists()) {
    throw new Error('Project not found');
  }

  const projectData = projectSnap.data() as Project;
  if (projectData.userId !== userId) {
    throw new Error('Unauthorized: You can only delete your own projects');
  }

  const queries = await getQueriesByProject(projectId);
  const queryIds = queries.map(q => q.id!);

  const metricsQuery = query(
    collection(db, COLLECTIONS.METRICS),
    where('projectId', '==', projectId)
  );
  const metricsSnapshot = await getDocs(metricsQuery);

  const contentsQuery = query(
    collection(db, COLLECTIONS.CONTENTS),
    where('projectId', '==', projectId)
  );
  const contentsSnapshot = await getDocs(contentsQuery);

  const answersQuery = query(
    collection(db, COLLECTIONS.ANSWERS),
    where('queryId', 'in', queryIds.length > 0 ? queryIds : [''])
  );
  const answersSnapshot = queryIds.length > 0 ? await getDocs(answersQuery) : { docs: [] };

  const membersRef = collection(db, COLLECTIONS.PROJECTS, projectId, COLLECTIONS.MEMBERS);
  const membersSnapshot = await getDocs(membersRef);

  const deletePromises = [
    ...metricsSnapshot.docs.map(doc => deleteDoc(doc.ref)),
    ...contentsSnapshot.docs.map(doc => deleteDoc(doc.ref)),
    ...answersSnapshot.docs.map(doc => deleteDoc(doc.ref)),
    ...queries.map(q => deleteDoc(doc(db, COLLECTIONS.QUERIES, q.id!))),
    deleteDoc(projectRef)
  ];

  for (const memberDoc of membersSnapshot.docs) {
    const memberData = memberDoc.data() as ProjectMember;
    deletePromises.push(deleteDoc(memberDoc.ref));

    if (memberData.userEmail) {
      const reverseIndexRef = doc(db, COLLECTIONS.USER_SHARED, memberData.userEmail, COLLECTIONS.PROJECTS, projectId);
      deletePromises.push(deleteDoc(reverseIndexRef));
    }
  }

  await Promise.all(deletePromises);
};

export const addProjectMember = async (projectId: string, memberEmail: string, role: 'editor' | 'viewer' = 'viewer') => {
  const userId = getUserId();
  const projectRef = doc(db, COLLECTIONS.PROJECTS, projectId);
  const projectSnap = await getDoc(projectRef);

  if (!projectSnap.exists()) {
    throw new Error('프로젝트를 찾을 수 없습니다');
  }

  const projectData = projectSnap.data() as Project;
  if (projectData.userId !== userId) {
    throw new Error('프로젝트 소유자만 멤버를 추가할 수 있습니다');
  }

  const membersRef = collection(db, COLLECTIONS.PROJECTS, projectId, COLLECTIONS.MEMBERS);
  const existingMemberQuery = query(
    membersRef,
    where('userEmail', '==', memberEmail)
  );
  const existingMemberSnap = await getDocs(existingMemberQuery);

  if (!existingMemberSnap.empty) {
    throw new Error('이미 프로젝트에 추가된 멤버입니다');
  }

  const batch = writeBatch(db);
  const now = Timestamp.now();

  const memberRef = doc(membersRef);
  batch.set(memberRef, {
    projectId,
    userId: '',
    userEmail: memberEmail,
    role,
    addedBy: userId,
    createdAt: now
  });

  const reverseIndexRef = doc(db, COLLECTIONS.USER_SHARED, memberEmail, COLLECTIONS.PROJECTS, projectId);
  batch.set(reverseIndexRef, {
    projectId,
    userEmail: memberEmail,
    role,
    sharedAt: now
  });

  await batch.commit();

  return memberRef.id;
};

export const getProjectMembers = async (projectId: string): Promise<ProjectMember[]> => {
  const membersRef = collection(db, COLLECTIONS.PROJECTS, projectId, COLLECTIONS.MEMBERS);
  const q = query(membersRef, orderBy('createdAt', 'desc'));

  const querySnapshot = await getDocs(q);
  return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as ProjectMember));
};

export const removeProjectMember = async (projectId: string, memberId: string) => {
  const userId = getUserId();

  const projectRef = doc(db, COLLECTIONS.PROJECTS, projectId);
  const projectSnap = await getDoc(projectRef);

  if (!projectSnap.exists()) {
    throw new Error('프로젝트를 찾을 수 없습니다');
  }

  const projectData = projectSnap.data() as Project;
  if (projectData.userId !== userId) {
    throw new Error('프로젝트 소유자만 멤버를 제거할 수 있습니다');
  }

  const memberRef = doc(db, COLLECTIONS.PROJECTS, projectId, COLLECTIONS.MEMBERS, memberId);
  const memberSnap = await getDoc(memberRef);

  if (!memberSnap.exists()) {
    throw new Error('멤버를 찾을 수 없습니다');
  }

  const memberData = memberSnap.data() as ProjectMember;

  const batch = writeBatch(db);

  batch.delete(memberRef);

  const reverseIndexRef = doc(db, COLLECTIONS.USER_SHARED, memberData.userEmail, COLLECTIONS.PROJECTS, projectId);
  batch.delete(reverseIndexRef);

  await batch.commit();
};

export const hasProjectAccess = async (projectId: string): Promise<boolean> => {
  const userId = getUserId();
  const user = auth.currentUser;

  const projectRef = doc(db, COLLECTIONS.PROJECTS, projectId);
  const projectSnap = await getDoc(projectRef);

  if (!projectSnap.exists()) {
    return false;
  }

  const projectData = projectSnap.data() as Project;
  if (projectData.userId === userId) {
    return true;
  }

  if (user?.email) {
    const reverseIndexRef = doc(db, COLLECTIONS.USER_SHARED, user.email, COLLECTIONS.PROJECTS, projectId);
    const reverseIndexSnap = await getDoc(reverseIndexRef);
    return reverseIndexSnap.exists();
  }

  return false;
};
