import { addJobLog } from '../db/firestore';

export const logger = {
  info: async (jobId: string, message: string) => {
    console.log(`[INFO] ${message}`);
    await addJobLog(jobId, { message, level: 'info' });
  },

  error: async (jobId: string, message: string) => {
    console.error(`[ERROR] ${message}`);
    await addJobLog(jobId, { message, level: 'error' });
  }
};
