import { generateQueries } from '../services/openai';
import { createQuery } from '../db/firestore';

export interface GenerateQueriesRequest {
  keyword: string;
  projectId: string;
}

export interface GenerateQueriesResponse {
  success: boolean;
  queryIds: string[];
  queries: string[];
  error?: string;
}

export const handleGenerateQueries = async (
  request: GenerateQueriesRequest
): Promise<GenerateQueriesResponse> => {
  try {
    const { keyword, projectId } = request;

    const queries = await generateQueries(keyword);

    const queryIds: string[] = [];

    for (const queryText of queries) {
      const queryId = await createQuery({
        projectId,
        text: queryText
      });
      queryIds.push(queryId);
    }

    return {
      success: true,
      queryIds,
      queries
    };
  } catch (error) {
    console.error('Error generating queries:', error);
    return {
      success: false,
      queryIds: [],
      queries: [],
      error: String(error)
    };
  }
};
