import { simulateAIAnswer } from '../services/openai';
import { getQueryDoc, getProject, createAnswer, createMetric } from '../db/firestore';
import { extractEntities, findEntityPositions, isRecommended, calculateScore } from '../utils/parser';
import { logger } from '../utils/logger';

export interface AnswerWorkerPayload {
  jobId: string;
  queryId: string;
  competitors?: string[];
}

export const processAnswer = async (payload: AnswerWorkerPayload) => {
  const { jobId, queryId, competitors = [] } = payload;

  try {
    await logger.info(jobId, `Processing answer for query: ${queryId}`);

    const queryDoc = await getQueryDoc(queryId);
    if (!queryDoc) {
      throw new Error(`Query not found: ${queryId}`);
    }

    const project = await getProject(queryDoc.projectId);
    if (!project) {
      throw new Error(`Project not found: ${queryDoc.projectId}`);
    }

    const targetBrand = project.targetKeyword;

    await logger.info(jobId, `Simulating AI answer for: ${queryDoc.text}`);

    const answer = await simulateAIAnswer(queryDoc.text);

    const entities = extractEntities(answer, targetBrand, competitors);
    const positions = findEntityPositions(answer, entities);

    const answerId = await createAnswer({
      queryId,
      platform: 'openai',
      answer,
      entities,
      positions,
      rawResponse: answer
    });

    await logger.info(jobId, `Answer created: ${answerId}`);

    const mention = entities.includes(targetBrand);
    const position = positions[targetBrand] || null;
    const isRec = mention ? isRecommended(answer, targetBrand) : false;
    const score = calculateScore(mention, position, isRec);

    const metricId = await createMetric({
      queryId,
      projectId: queryDoc.projectId,
      mention,
      position,
      isRecommended: isRec,
      competitors: entities.filter(e => e !== targetBrand),
      score
    });

    await logger.info(jobId, `Metric created: ${metricId}, Score: ${score}`);

    return {
      answerId,
      metricId,
      mention,
      score
    };
  } catch (error) {
    await logger.error(jobId, `Failed to process answer: ${error}`);
    throw error;
  }
};

export const processAnswerBatch = async (
  jobId: string,
  queryIds: string[],
  competitors: string[] = []
) => {
  const results = [];

  for (const queryId of queryIds) {
    try {
      const result = await processAnswer({ jobId, queryId, competitors });
      results.push({ queryId, success: true, ...result });
    } catch (error) {
      results.push({ queryId, success: false, error: String(error) });
    }
  }

  return results;
};
